import{_ as o,a0 as p,w as r,s as u,ao as l,I as n,x as t,a1 as s,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160603 How To Install And Use VBoxManage On Ubuntu 16.04 And Use Its Command line Options","title":"在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage","tag":"201607","desc":""},"relativePath":"201607/20160603 How To Install And Use VBoxManage On Ubuntu 16.04 And Use Its Command line Options.md","filePath":"[post].md"}'),d={name:"201607/20160603 How To Install And Use VBoxManage On Ubuntu 16.04 And Use Its Command line Options.md"};function g(h,a,b,c,k,x){const i=p("Link");return r(),u("div",null,[a[16]||(a[16]=l('<h1 id="在-linux-上安裝使用-virtualbox-的命令列管理界面-vboxmanage" tabindex="-1">在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage <a class="header-anchor" href="#在-linux-上安裝使用-virtualbox-的命令列管理界面-vboxmanage" aria-label="Permalink to “在 Linux 上安裝使用 VirtualBox 的命令列管理界面 VBoxManage”">​</a></h1><p>VirtualBox 擁有一套命令列工具，你可以使用 VirtualBox 的命令列界面 (CLI) 對遠程無界面的服務器上的虛擬機進行管理操作。在這篇教程中，你將會學到如何在沒有 GUI 的情況下使用 VBoxManage 創建、啓動一個虛擬機。VBoxManage 是 VirtualBox 的命令列界面，你可以在你的主機操作系統的命令列中用它來實現對 VirtualBox 的所有操作。VBoxManage 擁有圖形化用户界面所支持的全部功能，而且它支持的功能遠不止這些。它提供虛擬引擎的所有功能，甚至包含 GUI 還不能實現的那些功能。如果你想嘗試下不同的用户界面而不僅僅是 GUI，或者更改虛擬機更多高級和實驗性的配置，那麼你就需要用到命令列。</p><p>當你想要在 VirtualBox 上創建或運行虛擬機時，你會發現 VBoxManage 非常有用，你只需要使用遠程主機的終端就夠了。這對於需要遠程管理虛擬機的服務器來説是一種常見的情形。</p><h3 id="準備工作" tabindex="-1">準備工作 <a class="header-anchor" href="#準備工作" aria-label="Permalink to “準備工作”">​</a></h3><p>在開始使用 VBoxManage 的命令列工具前，確保在運行着 Ubuntu 16.04 的服務器上，你擁有超級用户的權限或者你能夠使用 sudo 命令，而且你已經在服務器上安裝了 Oracle Virtual Box。 然後你需要安裝 VirtualBox 擴展包，這是運行 VRDE 遠程桌面環境，訪問無界面虛擬機所必須的。</p><h3 id="安裝-vboxmanage" tabindex="-1">安裝 VBoxManage <a class="header-anchor" href="#安裝-vboxmanage" aria-label="Permalink to “安裝 VBoxManage”">​</a></h3>',6)),n("p",null,[a[1]||(a[1]=t("通過 ",-1)),s(i,{href:"https://www.virtualbox.org/wiki/Downloads"},{default:e(()=>[...a[0]||(a[0]=[t("Virtual Box 下載頁",-1)])]),_:1}),a[2]||(a[2]=t(" 這個鏈接，你能夠獲取你所需要的軟件擴展包的最新版本，擴展包的版本和你安裝的 VirtualBox 版本需要一致！",-1))]),a[17]||(a[17]=l(`<p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/12.png" alt=""></p><p>也可以用下面這條命令來獲取 VBoxManage 擴展。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://download.virtualbox.org/virtualbox/5.0.20/Oracle_VM_VirtualBox_Extension_Pack-5.0.20-106931.vbox-extpack</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/21.png" alt=""></p><p>運行下面這條命令，確認 VBoxManage 已經成功安裝在你的機器上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage list extpacks</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/31.png" alt=""></p><h3 id="在-ubuntu-16-04-上使用-vboxmanage" tabindex="-1">在 Ubuntu 16.04 上使用 VBoxManage <a class="header-anchor" href="#在-ubuntu-16-04-上使用-vboxmanage" aria-label="Permalink to “在 Ubuntu 16.04 上使用 VBoxManage”">​</a></h3><p>接下來我們將要使用 VBoxManage 向你展現通過命令列終端工具來新建和管理虛擬機是多麼的簡單。</p><p>運行下面的命令，新建一個將用來安裝 Ubuntu 系統的虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># VBoxManage createvm --name Ubuntu16.04 --register</span></span></code></pre></div><p>在運行了這條命令之後，VBoxMnage 將會新建一個叫 做“Ubuntu16.vbox” 的虛擬機，這個虛擬機的位置是家目錄路徑下的 “VirtualBox VMs/Ubuntu16/Ubuntu16.04.vbox”。在上面這條命令中，“createvm” 是用來新建虛擬機，“--name” 定義了虛擬機的名字，而 “registervm” 命令是用來註冊虛擬機的。</p><p>現在，使用下面這條命令為虛擬機創建一個硬盤鏡像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage createhd --filename Ubuntu16.04 --size 5124</span></span></code></pre></div><p>這裏，“createhd” 用來創建硬盤鏡像，“--filename” 用來指定虛擬機的名稱，也就是創建的硬盤鏡像名稱。“--size” 表示硬盤鏡像的空間容量，空間容量的單位總是 MB。我們指定了 5Gb，也就是 5124 MB。</p><p>接下來我們需要設置操作系統類型，如果要安裝 Linux 系的系統，那麼用下面這條命令指定系統類型為 Linux 或者 Ubuntu 或者 Fedora 之類的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage modifyvm Ubuntu16.04 --ostype Ubuntu</span></span></code></pre></div><p>用下面這條命令來設置虛擬系統的內存大小，也就是從主機中分配到虛擬機系統的內存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage modifyvm Ubuntu10.10 --memory 512</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/52.png" alt=""></p><p>現在用下面這個命令為虛擬機創建一個存儲控制器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage storagectl Ubuntu16.04 --name IDE --add ide --controller PIIX4 --bootable on</span></span></code></pre></div><p>這裏的 “storagect1” 是給虛擬機創建存儲控制器的，“--name” 指定了虛擬機裏需要創建、更改或者移除的存儲控制器的名稱。“--add” 選項指明存儲控制器所需要連接到的系統總線類型，可選的選項有 ide / sata / scsi / floppy。“--controller” 選擇主板的類型，主板需要根據需要的存儲控制器選擇，可選的選項有 LsiLogic / LSILogicSAS / BusLogic / IntelAhci / PIIX3 / PIIX4 / ICH6 / I82078。最後的 “--bootable” 表示控制器是否可以引導系統。</p><p>上面的命令創建了叫做 IDE 的存儲控制器。之後虛擬介質就能通過 “storageattach” 命令連接到該控制器。</p><p>然後運行下面這個命令來創建一個叫做 SATA 的存儲控制器，它將會連接到之後的硬盤鏡像上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage storagectl Ubuntu16.04 --name SATA --add sata --controller IntelAhci --bootable on</span></span></code></pre></div><p>將之前創建的硬盤鏡像和 CD/DVD 驅動器加載到 IDE 控制器。將 Ubuntu 的安裝光盤插到 CD/DVD 驅動器上。然後用 “storageattach” 命令連接存儲控制器和虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage storageattach Ubuntu16.04 --storagectl SATA --port 0 --device 0 --type hdd --medium &quot;your_iso_filepath&quot;</span></span></code></pre></div><p>這將把 SATA 存儲控制器及介質（比如之前創建的虛擬磁盤鏡像）連接到 Ubuntu16.04 虛擬機中。</p><p>運行下面的命令添加像網絡連接，音頻之類的功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage modifyvm Ubuntu10.10 --nic1 nat --nictype1 82540EM --cableconnected1 on</span></span>
<span class="line"><span>$ VBoxManage modifyvm Ubuntu10.10 --vram 128 --accelerate3d on --audio alsa --audiocontroller ac97</span></span></code></pre></div><p>通過指定你想要啓動虛擬機的名稱，用下面這個命令啓動虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ VBoxManage startvm Ubuntu16.04</span></span></code></pre></div><p>然後會打開一個新窗口，新窗口裏虛擬機通過關聯文件中引導。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/62.png" alt=""></p><p>你可以用接下來的命令來關掉虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage controlvm Ubuntu16.04 poweroff</span></span></code></pre></div><p>“controlvm” 命令用來控制虛擬機的狀態，可選的選項有 pause / resume / reset / poweroff / savestate / acpipowerbutton / acpisleepbutton。controlvm 有很多選項，用下面這個命令來查看它支持的所有選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$VBoxManage controlvm</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/81.png" alt=""></p><p>###完結</p><p>從這篇文章中，我們瞭解了 Oracle Virtual Box 中一個十分實用的工具 VBoxManage，文章包含了 VBoxManage 的安裝和在 Ubuntu 16.04 系統上的使用，包括通過 VBoxManage 中實用的命令來創建和管理虛擬機。希望這篇文章對你有幫助，另外別忘了分享你的評論或者建議。</p><hr>`,43)),n("p",null,[a[4]||(a[4]=t("via: ",-1)),s(i,{href:"http://linuxpitstop.com/install-and-use-command-line-tool-vboxmanage-on-ubuntu-16-04/"},{default:e(()=>[...a[3]||(a[3]=[t("http://linuxpitstop.com/install-and-use-command-line-tool-vboxmanage-on-ubuntu-16-04/",-1)])]),_:1})]),n("p",null,[a[8]||(a[8]=t("作者：",-1)),s(i,{href:"http://linuxpitstop.com/author/kashif/"},{default:e(()=>[...a[5]||(a[5]=[t("Kashif",-1)])]),_:1}),a[9]||(a[9]=t(" 譯者：",-1)),s(i,{href:"https://github.com/GitFuture"},{default:e(()=>[...a[6]||(a[6]=[t("GitFuture",-1)])]),_:1}),a[10]||(a[10]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:e(()=>[...a[7]||(a[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[13]||(a[13]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[11]||(a[11]=[t("LCTT",-1)])]),_:1}),a[14]||(a[14]=t(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:e(()=>[...a[12]||(a[12]=[t("Linux中國",-1)])]),_:1}),a[15]||(a[15]=t(" 榮譽推出",-1))])])}const B=o(d,[["render",g]]);export{V as __pageData,B as default};
